const mesures = [];
const mesurer = async (nom, fn) => {
  const t = performance.now();
  await fn();
  const ms = Math.round(performance.now() - t);
  mesures.push([nom, ms]);
  console.log(`⏱ ${nom} : ${ms} ms`);

